package com.dataengine.governance.service;
import com.dataengine.governance.domain.*; import com.dataengine.governance.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class QualityGovernanceService {
 private final QualityRuleRepository rules; private final QualityResultRepository results; private final DataChangeRepository changes;
 public QualityGovernanceService(QualityRuleRepository r,QualityResultRepository q,DataChangeRepository c){rules=r;results=q;changes=c;}
 @Transactional(readOnly=true) public List<QualityRule> rules(){return rules.findAll();} @Transactional(readOnly=true) public List<QualityResult> results(UUID changeId){return results.findByChangeIdOrderByCreatedAtDesc(changeId);}
 public QualityRule create(String asset,String name,String metric,double threshold,GateStatus severity,String owner){return rules.save(new QualityRule(asset,name,metric,threshold,severity,owner));}
 public QualityResult evaluate(UUID changeId,UUID ruleId,double observed,String actor){DataChange change=requireChange(changeId);QualityRule rule=rules.findById(ruleId).orElseThrow(()->new GovernanceException("质量规则不存在"));if(!rule.isEnabled())throw new GovernanceException("质量规则已停用");if(!rule.getAssetQualifiedName().equals(change.getAssetQualifiedName()))throw new GovernanceException("质量规则与变更资产不匹配");GateStatus gate=observed<=rule.getThreshold()?GateStatus.PASS:rule.getSeverity();QualityResult result=results.save(new QualityResult(changeId,ruleId,observed,rule.getThreshold(),gate,rule.getMetric()+"="+observed+"，阈值="+rule.getThreshold()));recalculate(change);return result;}
 public QualityResult acknowledge(UUID resultId,String actor,String reason){return decide(resultId,QualityResultStatus.ACKNOWLEDGED,actor,reason);} public QualityResult waive(UUID resultId,String actor,String reason){return decide(resultId,QualityResultStatus.WAIVED,actor,reason);} public QualityResult resolve(UUID resultId,String actor,String reason){return decide(resultId,QualityResultStatus.RESOLVED,actor,reason);}
 private QualityResult decide(UUID id,QualityResultStatus status,String actor,String reason){if(reason==null||reason.isBlank())throw new GovernanceException("质量处置必须填写原因");QualityResult r=results.findById(id).orElseThrow(()->new GovernanceException("质量结果不存在"));if(r.getStatus()==QualityResultStatus.PASSED)throw new GovernanceException("通过的质量结果无需处置");r.decide(status,actor,reason);recalculate(requireChange(r.getChangeId()));return r;}
 private void recalculate(DataChange change){List<QualityResult> all=results.findByChangeIdOrderByCreatedAtDesc(change.getId());boolean block=all.stream().anyMatch(x->x.getGate()==GateStatus.BLOCK&&Set.of(QualityResultStatus.OPEN,QualityResultStatus.ACKNOWLEDGED).contains(x.getStatus()));boolean warn=all.stream().anyMatch(x->x.getGate()==GateStatus.WARN&&Set.of(QualityResultStatus.OPEN,QualityResultStatus.ACKNOWLEDGED).contains(x.getStatus()));change.setQualityGate(block?GateStatus.BLOCK:warn?GateStatus.WARN:GateStatus.PASS);changes.save(change);}
 private DataChange requireChange(UUID id){return changes.findById(id).orElseThrow(()->new GovernanceException("Data Change 不存在"));}
}
